<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Content; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Storage;
class ContentController extends Controller {
 private function type(Request $r): string { return $r->route('type') ?? match($r->segment(2)){ 'services'=>'service','projects'=>'project','posts'=>'post' }; }
 private function route(Content $c): string { return 'admin.'.match($c->type){'service'=>'services','project'=>'projects','post'=>'posts'}.'.index'; }
 public function index(Request $r){ $type=$this->type($r); return view('admin.content.index',['items'=>Content::where('type',$type)->when($r->q,fn($q,$v)=>$q->where('title','like',"%$v%"))->latest()->paginate(12),'type'=>$type]); }
 public function create(Request $r){ return view('admin.content.form',['item'=>new Content(['type'=>$this->type($r),'status'=>'draft']),'type'=>$this->type($r)]); }
 public function store(Request $r){ $type=$this->type($r); $data=$this->validated($r); DB::transaction(function() use($r,$data,$type,&$item){ if($r->hasFile('cover')) $data['cover_path']=$r->file('cover')->store('content','public'); $data['type']=$type; if($data['status']==='published') $data['published_at']=$data['published_at']??now(); $item=Content::create($data); }); return redirect()->route($this->route($item))->with('success','Contenido creado sin modificar publicaciones anteriores.'); }
 public function edit(Request $r, Content $content){ abort_unless($content->type===$this->type($r),404); return view('admin.content.form',['item'=>$content,'type'=>$content->type]); }
 public function update(Request $r, Content $content){ abort_unless($content->type===$this->type($r),404); $data=$this->validated($r,$content); DB::transaction(function() use($r,$data,$content){ if($r->hasFile('cover')) $data['cover_path']=$r->file('cover')->store('content','public'); if($data['status']==='published'&&!$content->published_at) $data['published_at']=now(); $content->update($data); }); return redirect()->route($this->route($content))->with('success','Contenido actualizado.'); }
 public function destroy(Request $r, Content $content){ abort_unless($content->type===$this->type($r),404); $content->update(['status'=>'archived']); $content->delete(); return back()->with('success','El elemento fue archivado y puede restaurarse.'); }
 public function status(Request $r,string $type,Content $content){ abort_unless($content->type===$type,404); $data=$r->validate(['status'=>'required|in:draft,published,archived']); $content->update(['status'=>$data['status'],'published_at'=>$data['status']==='published'?($content->published_at??now()):$content->published_at]); return back()->with('success','Estado actualizado.'); }
 public function archived(string $type){ return view('admin.content.index',['items'=>Content::onlyTrashed()->where('type',$type)->latest()->paginate(12),'type'=>$type,'archived'=>true]); }
 private function validated(Request $r,?Content $content=null): array { $data=$r->validate(['title'=>'required|string|max:160','excerpt'=>'nullable|string|max:500','body'=>'nullable|string|max:20000','location'=>'nullable|string|max:150','category'=>'nullable|string|max:80','cover'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:4096','status'=>'required|in:draft,published,archived','published_at'=>'nullable|date','meta_description'=>'nullable|string|max:160']); $data['slug']=Content::uniqueSlug($data['title'],$content?->id); return $data; }
}
